@startuml

class RepairShop {
  + name : string
  + address : string
  + number_of_employees : int
}

class Employee {
  + tax_code : string
  + address : string
  + phone_number : string
  + years_of_service : int
}

class Director extends Employee {
  + age : int
}

class Repair {
  + code : string
  + check_in_date : date
  + check_in_time : time
  + return_date : date
  + return_time : time
}

class Vehicle {
  + model : string
  + type : string
  + license_plate : string
  + year_of_registration : int
}

class Owner {
  + tax_code : string
  + address : string
  + phone_number : string
}

RepairShop "1" *-- "1..*" Employee : employs
RepairShop "1" -- "1" Director : managed by
RepairShop "1" -- "*" Repair : performs
Repair "1" -- "1" Vehicle : involves
Vehicle "1" -- "1" Owner : owned by
Owner "1" -- "*" Vehicle : owns

@enduml

